# a computer-use loop: model sees a screenshot, emits a UI action
def computer_use_step(screenshot):
    action = model.decide(screenshot)   # e.g. click / type / key
    if action.type == "click":
        os_control.click(action.x, action.y)
    elif action.type == "type":
        os_control.type(action.text)
    elif action.type == "key":
        os_control.press(action.key)     # e.g. 'cmd+s'
    return capture_screenshot()          # observe the new screen
# note: 'click anywhere / type anything' == an unbounded action space

# a browser agent step; the PAGE CONTENT is untrusted input
def browser_step(page):
    text = page.get_visible_text()       # <-- may contain injected
                                          #     'ignore instructions...'
    action = model.decide(page.url, text)
    if action.type == "click":
        page.click(action.selector)
    elif action.type == "fill":
        page.fill(action.selector, action.value)
    elif action.type == "navigate":
        page.goto(action.url)            # could be attacker-chosen!
    return page
# treat everything read from the page as hostile until proven safe

def guarded_action(action):
    # 1. SANDBOX: everything runs isolated, no host creds
    if not sandbox.active:
        raise RuntimeError("refuse to act outside sandbox")
    # 2. SCOPE: allowlist the action space
    if not allowlist.permits(action):
        raise PermissionError(f"blocked: {action}")
    # 3. CONFIRM: gate irreversible / high-impact actions on a human
    if action.is_consequential:            # spend, delete, external send
        if not human_approves(action):
            return "cancelled by reviewer"
    return sandbox.perform(action)
# defense in depth: sandbox + scope + confirmation

